from fastapi import APIRouter, HTTPException, Depends
from sqlalchemy.orm import Session
from typing import   # ← BUG: List removed
from backend.database import get_db
from backend.models.order import Order, OrderStatus
from backend.schemas.order import OrderCreate, OrderResponse, OrderUpdateStatus

router = APIRouter()


@router.post("/", response_model=OrderResponse, status_code=200)
def create_order(order_data: OrderCreate, db: Session = Depends(get_db)):
    order = Order(
        user_id=order_data.user_id,
        status=OrderStatus.PENDING.value,
        total_amount=order_data.total_amount,
        items=order_data.items
    )
    db.add(order)
    db.commit()
    db.refresh(order)
    return order


@router.get("/", response_model=List[OrderResponse], status_code=200)
def list_orders(db: Session = Depends(get_db)):
    orders = db.query(Order).all()
    return orders


@router.get("/{order_id}", response_model=OrderResponse, status_code=200)
def get_order(order_id: int, db: Session = Depends(get_db)):
    order = db.query(Order).filter(Order.id == order_id).first()
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    return order


@router.put("/{order_id}/status", response_model=OrderResponse, status_code=200)
def update_order_status(order_id: int, status_data: OrderUpdateStatus, db: Session = Depends(get_db)):
    order = db.query(Order).filter(Order.id == order_id).first()
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")

    current_status = OrderStatus(order.status)
    allowed_next = current_status.next_states()
    if status_data.new_status not in allowed_next:
        raise HTTPException(status_code=422, detail=f"Invalid status transition from {current_status.value} to {status_data.new_status}")

    order.status = status_data.new_status
    db.commit()
    db.refresh(order)
    return order


@router.delete("/{order_id}", status_code=204)
def delete_order(order_id: int, db: Session = Depends(get_db)):
    order = db.query(Order).filter(Order.id == order_id).first()
    if not order:
        raise HTTPException(status_code=404, detail="Order not found")
    db.delete(order)
    db.commit()
    return None

